import{_ as e,o as n,c as t,a2 as o}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Frequently Asked Questions (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":null}'),r={name:"guide/faq.md"};function i(d,a,s,l,m,c){return n(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="frequently-asked-questions-faq" tabindex="-1">Frequently Asked Questions (FAQ) <a class="header-anchor" href="#frequently-asked-questions-faq" aria-label="Permalink to &quot;Frequently Asked Questions (FAQ)&quot;">​</a></h1><p>Berikut adalah beberapa pertanyaan yang sering diajukan mengenai Zhuxe Asistance.</p><h2 id="bot-saya-error-cannot-find-module-saat-dijalankan-kenapa" tabindex="-1">Bot saya error &quot;Cannot find module&quot; saat dijalankan, kenapa? <a class="header-anchor" href="#bot-saya-error-cannot-find-module-saat-dijalankan-kenapa" aria-label="Permalink to &quot;Bot saya error &quot;Cannot find module&quot; saat dijalankan, kenapa?&quot;">​</a></h2><p>Biasanya ini terjadi karena folder <code>dist</code> tidak ikut ter-<em>build</em> atau Anda belum menjalankan <code>npm install</code>. Pastikan Anda menjalankan <code>npm install</code> di folder proyek dan tidak menghapus folder <code>node_modules</code>.</p><h2 id="bagaimana-cara-agar-bot-tetap-online-24-jam" tabindex="-1">Bagaimana cara agar bot tetap online 24 jam? <a class="header-anchor" href="#bagaimana-cara-agar-bot-tetap-online-24-jam" aria-label="Permalink to &quot;Bagaimana cara agar bot tetap online 24 jam?&quot;">​</a></h2><p>Jangan jalankan bot menggunakan <code>node index.js</code> biasa di terminal. Gunakan <em>process manager</em> seperti <strong>PM2</strong> atau jalankan di dalam panel Pterodactyl (seperti yang sedang Anda gunakan).</p><h2 id="apakah-nomor-whatsapp-saya-bisa-ter-banned" tabindex="-1">Apakah nomor WhatsApp saya bisa ter-banned? <a class="header-anchor" href="#apakah-nomor-whatsapp-saya-bisa-ter-banned" aria-label="Permalink to &quot;Apakah nomor WhatsApp saya bisa ter-banned?&quot;">​</a></h2><p>Ya, WhatsApp memiliki sistem anti-spam yang ketat. <strong>Jangan pernah</strong> menggunakan bot untuk mengirim pesan massal (<em>broadcast</em>) ke nomor yang tidak menyimpan nomor Anda. Gunakan bot secara wajar.</p><h2 id="bagaimana-cara-mengganti-dari-scan-qr-ke-pairing-code" tabindex="-1">Bagaimana cara mengganti dari Scan QR ke Pairing Code? <a class="header-anchor" href="#bagaimana-cara-mengganti-dari-scan-qr-ke-pairing-code" aria-label="Permalink to &quot;Bagaimana cara mengganti dari Scan QR ke Pairing Code?&quot;">​</a></h2><p>Buka file <code>config.js</code> di proyek bot Anda, lalu ubah <code>usePairingCode: false</code> menjadi <code>usePairingCode: true</code>. Jangan lupa isi <code>pairingNumber</code> dengan nomor bot Anda.</p>',10)])])}const g=e(r,[["render",i]]);export{u as __pageData,g as default};
